insert into tadabbur.reflections (recitation_id, answer_text, favourite_surah, favourite_ayah, id, question_key) values
  ('00000000-0000-4000-8000-cccc00000001', 'I recite this after long night shifts. It is a promise I need to hear out loud.', null, null, '00000000-0000-4000-8000-dddd00000001', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000001', null, 94, 5, '00000000-0000-4000-8000-dddd00000002', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000001', 'My grandfather taught me in Bangladesh before I could read English.', null, null, '00000000-0000-4000-8000-dddd00000003', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000002', 'At Fajr the hall is quiet. Ar-Rahman fills it with a question I never tire of.', null, null, '00000000-0000-4000-8000-dddd00000004', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000002', null, 55, 13, '00000000-0000-4000-8000-dddd00000005', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000002', 'Memorised it as a boy in Adhamiyah. I recite it the way my teacher did.', null, null, '00000000-0000-4000-8000-dddd00000006', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000003', 'I chose it for a friend going through a hard year. It is a surah of reassurance.', null, null, '00000000-0000-4000-8000-dddd00000007', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000003', null, 93, 4, '00000000-0000-4000-8000-dddd00000008', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000003', 'I started tajweed classes at 22. This was my first full surah with proper makharij.', null, null, '00000000-0000-4000-8000-dddd00000009', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000004', 'My dad recites Al-Mulk every night. Leading it in Taraweeh felt like giving it back to him.', null, null, '00000000-0000-4000-8000-dddd00000010', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000004', null, 67, 2, '00000000-0000-4000-8000-dddd00000011', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000004', 'Hifz completed at 15 at the local madrasah.', null, null, '00000000-0000-4000-8000-dddd00000012', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000005', 'Short, but it holds everything. I recite it between batches at the bakery too.', null, null, '00000000-0000-4000-8000-dddd00000013', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000005', null, 112, 1, '00000000-0000-4000-8000-dddd00000014', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000005', 'In Kayseri, from the imam of our neighbourhood masjid.', null, null, '00000000-0000-4000-8000-dddd00000015', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000006', 'London traffic tests your patience. This ayah is how I reset between shifts.', null, null, '00000000-0000-4000-8000-dddd00000016', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000006', null, 13, 28, '00000000-0000-4000-8000-dddd00000017', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000006', 'Dugsi in Mogadishu, then Saturday classes in Tottenham.', null, null, '00000000-0000-4000-8000-dddd00000018', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000007', 'We recite it in every prayer. I wanted to slow down and mean every word.', null, null, '00000000-0000-4000-8000-dddd00000019', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000007', null, 1, 6, '00000000-0000-4000-8000-dddd00000020', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000007', 'From my mother at the kitchen table.', null, null, '00000000-0000-4000-8000-dddd00000021', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000008', 'Recited for my nani the week after she passed. It is the ayah of greeting in Paradise.', null, null, '00000000-0000-4000-8000-dddd00000022', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000008', null, 36, 58, '00000000-0000-4000-8000-dddd00000023', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000008', 'Evening madrasah above a shop on the Broadway.', null, null, '00000000-0000-4000-8000-dddd00000024', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000009', 'I teach this to my pupils'' mums. Three ayat that sum up how to live.', null, null, '00000000-0000-4000-8000-dddd00000025', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000009', null, 103, 3, '00000000-0000-4000-8000-dddd00000026', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000009', 'Warsh recitation from my father, Hafs from London teachers.', null, null, '00000000-0000-4000-8000-dddd00000027', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000010', 'It sits in the middle of the fasting ayat. Allah says He is near, right when we are hungry.', null, null, '00000000-0000-4000-8000-dddd00000028', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000010', null, 2, 186, '00000000-0000-4000-8000-dddd00000029', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000010', 'Mosque school in Lahore, refreshed with my son''s teacher here.', null, null, '00000000-0000-4000-8000-dddd00000030', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000011', 'The most hopeful ayah I know. Hospital life needs it.', null, null, '00000000-0000-4000-8000-dddd00000031', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000011', null, 39, 53, '00000000-0000-4000-8000-dddd00000032', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000011', 'Weekend madrasah, then an online ijazah course during med school.', null, null, '00000000-0000-4000-8000-dddd00000033', 'where_learned'),
  ('00000000-0000-4000-8000-cccc00000012', 'My son just memorised it. I led Fajr with it so he could hear his surah in the masjid.', null, null, '00000000-0000-4000-8000-dddd00000034', 'why_surah'),
  ('00000000-0000-4000-8000-cccc00000012', null, 112, 4, '00000000-0000-4000-8000-dddd00000035', 'favourite_ayah'),
  ('00000000-0000-4000-8000-cccc00000012', 'From an imam in Ibadan, polished at the Woolwich circle.', null, null, '00000000-0000-4000-8000-dddd00000036', 'where_learned')
